extern "C" void *memmove(void *, const void *, unsigned int);
extern "C" void *arch_malloc(unsigned int, const char *, int);
extern "C" void arch_free(void *);

template<int __inst>
class __malloc_alloc_template {
public:
  static void *_S_oom_malloc(unsigned int);
  static void *allocate(unsigned int __n) {
    void *__result = arch_malloc(__n, __FILE__, 0);
    if (0 == __result) __result = _S_oom_malloc(__n);
    return __result;
  }
  static void deallocate(void *__p, unsigned int) {
    arch_free(__p);
  }
};

template<class _Tp>
inline _Tp *copy(const _Tp *__first, const _Tp *__last, _Tp *__result) {
  memmove(__result, __first, sizeof(_Tp) * (__last - __first));
  return __result + (__last - __first);
}

template<class _Tp>
inline _Tp *uninitialized_copy(const _Tp *__first, const _Tp *__last,
                               _Tp *__result) {
  return copy(__first, __last, __result);
}

template<class _Tp>
inline void destroy(_Tp *, _Tp *) {}

template<class _Tp, class _Alloc>
class _Vector_base {
protected:
  _Tp *_M_start;
  _Tp *_M_finish;
  _Tp *_M_end_of_storage;

  _Tp *_M_allocate(unsigned int __n) {
    return __n ? (_Tp *)_Alloc::allocate(__n * sizeof(_Tp)) : 0;
  }
  void _M_deallocate(_Tp *__p, unsigned int __n) {
    if (__n != 0) _Alloc::deallocate(__p, __n * sizeof(_Tp));
  }
};

template<class _Tp, class _Alloc>
class vector : protected _Vector_base<_Tp, _Alloc> {
public:
  typedef _Tp value_type;
  typedef value_type *iterator;
  typedef const value_type *const_iterator;
  typedef unsigned int size_type;

  iterator begin() { return _M_start; }
  const_iterator begin() const { return _M_start; }
  iterator end() { return _M_finish; }
  const_iterator end() const { return _M_finish; }
  size_type size() const { return size_type(_M_finish - _M_start); }
  size_type capacity() const {
    return size_type(_M_end_of_storage - _M_start);
  }
  iterator _M_allocate_and_copy(size_type __n, const_iterator __first,
                                const_iterator __last) {
    iterator __result = _M_allocate(__n);
    uninitialized_copy(__first, __last, __result);
    return __result;
  }

  vector<_Tp, _Alloc> &operator=(const vector<_Tp, _Alloc> &__x);
};

template<class _Tp, class _Alloc>
vector<_Tp, _Alloc> &
vector<_Tp, _Alloc>::operator=(const vector<_Tp, _Alloc> &__x)
{
  if (&__x != this) {
    const size_type __xlen = __x.size();
    if (__xlen > capacity()) {
      iterator __tmp = _M_allocate_and_copy(__xlen, __x.begin(), __x.end());
      destroy(_M_start, _M_finish);
      _M_deallocate(_M_start, _M_end_of_storage - _M_start);
      _M_start = __tmp;
      _M_end_of_storage = _M_start + __xlen;
    }
    else if (size() >= __xlen) {
      iterator __i = copy(__x.begin(), __x.end(), begin());
      destroy(__i, _M_finish);
    }
    else {
      copy(__x.begin(), __x.begin() + size(), _M_start);
      uninitialized_copy(__x.begin() + size(), __x.end(), _M_finish);
    }
    _M_finish = _M_start + __xlen;
  }
  return *this;
}

